def compute_task_utilization(task):
    return task.C / task.T

def compute_global_utilization(task_set):
    U = 0
    for task in task_set:
        U += compute_task_utilization(task)
    return U

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return (a * b) // gcd(a, b)

def compute_hyper_period(task_set):
    if not task_set:
        return 1
    periods = [task.T for task in task_set]
    result_lcm = periods[0]
    for i in range(1, len(periods)):
        result_lcm = lcm(result_lcm, periods[i])
    return result_lcm

def add_state_selection_constraints(milp_model, num_intervals, num_low_power_states, q_k_values):
    for k in range(num_intervals):
        if q_k_values[k] > 0:
            # Constraint: Exactly one low-power state must be chosen
            milp_model.add_constraint(sum(LP_s_k[s][k] for s in range(num_low_power_states)) == 1)
        else:
            # Constraint: No low-power state chosen if no idle time
            for s in range(num_low_power_states):
                milp_model.add_constraint(LP_s_k[s][k] == 0)

# LP_s_k is a 2D array/matrix representing the binary variables.

def add_bet_constraints(milp_model, num_intervals, num_low_power_states, q_k_values, BET_values):
    for k in range(num_intervals):
        for s in range(num_low_power_states):
            # If idle period is too short for state s, then state s cannot be chosen
            if q_k_values[k] <= BET_values[s]:
                milp_model.add_constraint(LP_s_k[s][k] == 0)

# LP_s_k is the binary variable matrix.

